    /// §scxml-6.4 fixes for a child: the top-level `<data>`, each declared with the value the parent
    /// handed it in place of its own; the early-bound `<data>` of the states, which take none; the
    /// top-level scripts, which read the handed values; then the initial configuration is entered.
    public func initializeDataModel(engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        pendingEventMetadata = EventMetadata()
        // §scxml-6.4: the values the parent handed are this start's, taken once.
        let handed = invokeSeeds
        invokeSeeds = [:]
        defineData("nothing", handed: handed["nothing"], as: "nil", engine: engine)
        defineData("sawParamError", handed: handed["sawParamError"], as: "0", engine: engine)
    }

    /// Keeps the metadata of the event about to be selected on (§scxml-5.10).
    public func populateEventMetadata(_ metadata: EventMetadata) {
        pendingEventMetadata = metadata
    }

    /// W3C SCXML 5.10: binds the event whose transitions are about to be selected as the `_event`
    /// their guards read, whole, so a field it does not carry is absent. The null event is an
    /// eventless selection, which has no event of its own, so `_event` stays what it was.
    public func bindCurrentEvent(_ event: InvokeParamErrorStartsTheChildEvent, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        guard event != .null else {
            return
        }
        let metadata = pendingEventMetadata
        let name = metadata.name.isEmpty ? getEventName(event) : metadata.name
        do {
            let reading = try scriptSession.bindCurrentEvent(
                LuaEvent(
                    name: name,
                    type: metadata.eventType.description,
                    sendID: metadata.sendID,
                    // W3C SCXML 5.10.1 + C.1 (docs/adr/0090): `_event.origin` and
                    // `_event.origintype` are the two fields of the one pair the delivering
                    // processor wrote where it built the event, read here as they are: for an
                    // event a session sent, the location the sender published (test 336). An
                    // event no processor stamped hands both over as the empty text, which the
                    // binding leaves blank: undefined to the document, never `''`.
                    origin: metadata.originAddress,
                    originType: metadata.originProcessor,
                    invokeID: metadata.invokeID,
                    data: metadata.data
                ))
            // W3C SCXML B.2.8.1: which rung the payload got is known only here, where the ladder was
            // climbed, so the engine is told now. One a host sent as structure and the datamodel
            // refused is the reading the engine counts (`Engine.undecodablePayloads`); without
            // this call the payload is lost to the document and to the host alike.
            engine.notePayloadReading(event, reading: Self.payloadReading(of: reading))
        } catch {
            raiseExecutionError("_event could not be bound for '\(name)'", engine: engine)
        }
    }

    /// The engine's name for a rung the script engine reports: the two modules each declare the
    /// five readings, since the script engine does not depend on the runtime.
    private static func payloadReading(of reading: SceLua.PayloadReading) -> SceRuntime.PayloadReading {
        switch reading {
        case .absent: return .absent
        case .dom: return .dom
        case .structured: return .structured
        case .text: return .text
        case .undecodable: return .undecodable
        }
    }

    /// W3C SCXML 5.9.1: a `cond` that cannot be evaluated is false, and raises `error.execution`.
    private func evaluateGuard(_ condition: String, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) -> Bool {
        var failed = false
        return evaluateCond(condition, of: "<transition>", failed: &failed, engine: engine)
    }

    /// W3C SCXML 4.3, 5.9.1: the same for the `cond` of an `<if>` or `<elseif>`, which also says that
    /// it failed, because the element that held it ends its block once the chain has run (§scxml-4.9).
    private func evaluateIfCond(_ condition: String, failed: inout Bool, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) -> Bool {
        evaluateCond(condition, of: "<if>", failed: &failed, engine: engine)
    }

    private func evaluateCond(
        _ condition: String,
        of element: String,
        failed: inout Bool,
        engine: Engine<InvokeParamErrorStartsTheChildPolicy>
    ) -> Bool {
        do {
            return try scriptSession.evaluateCondition(condition, chunkName: "=cond")
        } catch {
            raiseExecutionError("a \(element) cond failed to evaluate", engine: engine)
            failed = true
            return false
        }
    }


    // ------------------------------------------------------------------
    // Child sessions (W3C SCXML 6.4)
    // ------------------------------------------------------------------

    /// W3C SCXML 6.4: the `<invoke>`s a state's entry deferred to the end of the
    /// macrostep. A state exited before then drops its own.
    private var pendingInvokes: [PendingInvoke<InvokeParamErrorStartsTheChildState>] = []

    /// W3C SCXML 6.4.1: the invocations running, by the id their `<invoke>` carries.
    private var activeInvokes: [String: ChildSession] = [:]

    /// The session `<invoke>` `inv_probe` started, while its state is active.
    private var sceInvokeChildInvProbe: InvokedSession<InvokeParamErrorStartsTheChildSceSynthInvokeInvProbePolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneInvProbe = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsInvProbe = 0

    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("inv_probe".utf8) {
                sceStartInvokeInvProbe(pending, engine: engine)
                return
            }
        }
    }

    /// Starts the session of `<invoke>` `inv_probe` (W3C SCXML 6.4).
    private func sceStartInvokeInvProbe(_ pending: PendingInvoke<InvokeParamErrorStartsTheChildState>, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        // W3C SCXML C.1: the child is known by the id its parent mints for it and
        // keys the invocation on, so the sender of what it sends is the id it
        // publishes in `_ioprocessors`.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let childPolicy = InvokeParamErrorStartsTheChildSceSynthInvokeInvProbePolicy()
#if DEBUG
        // docs/adr/0096: a test that fails this session's steps on request fails the child's too.
        childPolicy.sceScriptSessionFault = sceScriptSessionFault
#endif
        // W3C SCXML 6.4.1: the child is handed the values this invoke names before it
        // initializes.
        var seeds: [String: LuaSeed] = [:]
        seeds["kept"] = .scalar(.string("here"))
        if let seedValue = evaluateSeed("nothing.deep") {
            seeds["broken"] = seedValue
        } else {
            raiseExecutionError("<invoke> <param name='broken'> could not be read", engine: engine)
        }
        childPolicy.acceptSeeds(seeds)

        let session = InvokedSession(
            policy: childPolicy,
            sessionID: childSessionID,
            queue: ParentEventQueue(parentSessionID: sessionID)
        )
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["inv_probe"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "inv_probe",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        // W3C SCXML 6.4: the child's delayed sends are measured on this machine's
        // clock, so a delay on either side of the boundary is the same instant and a
        // clock its host advances moves the child too.
        session.engine.setClock(engine.clock())
        // SCE_MESH.md §21.3: the child's router is the one the factory answers for this invoke
        // and this document (empty for a child written in line), installed before the child
        // initializes, since its first state may already send.
        engine.startChildMesh(of: session, invokeID: "inv_probe", document: documentStem("#invoke_param_error_starts_the_child__sce_synth_invoke__inv_probe"))
        guard startChildSession(session, invokeID: "inv_probe", engine: engine) else {
            // docs/adr/0096: the child's start was refused, so the invoke ends without a child:
            // it is not kept, and `startChildSession` raised the error.execution that says so.
            activeInvokes["inv_probe"] = nil
            return
        }
        sceInvokeChildInvProbe = session
        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeInvProbe(engine: engine)
    }

    /// Takes what the session of `<invoke>` `inv_probe` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeInvProbe(engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        guard let child = sceInvokeChildInvProbe, !sceInvokeDoneInvProbe else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "inv_probe",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneInvProbe = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "inv_probe", donedata: child.donedataAtFinal, engine: engine)
        }
    }

    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        if !sceInvokeDoneInvProbe, let child = sceInvokeChildInvProbe {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "inv_probe",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeInvProbe(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        sceSettleInvokeInvProbe(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneInvProbe, let due = sceInvokeChildInvProbe?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("inv_probe".utf8) {
            if let child = sceInvokeChildInvProbe, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("inv_probe".utf8) {
            return sceInvokeChildInvProbe.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["inv_probe"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildInvProbe.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["inv_probe"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildInvProbe {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: InvokeParamErrorStartsTheChildState, engine: Engine<InvokeParamErrorStartsTheChildPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .paramPhase:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {

                // W3C SCXML 6.2: send id="__send_0"
                do {
                    let sendEventData = ""
                    do {
                    // W3C SCXML 6.2 / C.1: deliver the event to this session's own external
                    // queue, carrying the pair the SCXML processor writes for this session as
                    // its origin and this session as its sender (docs/adr/0090).
                        // W3C SCXML 6.2: delayed to this session's external queue.
                        engine.scheduleEvent(
                            InvokeParamErrorStartsTheChildEvent.timeout,
                            delay: Duration.milliseconds(3000),
                            sendID: "__send_0",
                            eventData: sendEventData,
                            sender: self.sessionID
                        )
                    }
                }
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsInvProbe += 1
                let generatedInvokeID = "paramPhase.\(sceInvokeStartsInvProbe).inv_probe"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .paramPhase,
                    documentID: "inv_probe"
                ))
            }
        default:
            break  // No entry actions
        }
    }

    /// Runs a `<history>`'s default transition content (W3C SCXML 3.10.2), after
    /// its parent's onentry (and after the parent's own `<initial>` content) when
    /// the history was taken with nothing recorded. The engine asks for it by the
    /// entry set's defaultHistoryContent answer; a history that restored what it
    /// recorded runs nothing.
    public func executeHistoryDefaultContent(_ history: HistoryID, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        // W3C SCXML 3.10.2: no <history> in this document has default content.
    }

    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: InvokeParamErrorStartsTheChildState, engine: Engine<InvokeParamErrorStartsTheChildPolicy>, configurationBeforeExit: [InvokeParamErrorStartsTheChildState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .paramPhase:
            cancelInvokesForState(&pendingInvokes, .paramPhase)
            sceInvokeChildInvProbe?.stop()
            sceInvokeChildInvProbe?.detachMesh()
            sceInvokeChildInvProbe = nil
            activeInvokes["inv_probe"] = nil
            sceInvokeDoneInvProbe = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: InvokeParamErrorStartsTheChildState,
        event: InvokeParamErrorStartsTheChildEvent,
        engine: Engine<InvokeParamErrorStartsTheChildPolicy>
    ) -> EnabledTransition<InvokeParamErrorStartsTheChildState>? {
        switch state {
        case .paramPhase:
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .childUp {
                // W3C SCXML 5.9: cond="sawParamError !== 1" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(sawParamError ~= 1)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failNoParamError)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .childUp {
                // W3C SCXML 5.9: cond="_event.data.kept !== 'here'" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(_event.data.kept ~= \"here\")", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failGoodParamLost)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .childUp {
                // W3C SCXML 5.9: cond="_event.data.brokenPlaceholder === true" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(_event.data.brokenPlaceholder == true)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failBrokenParamSeeded)],
                        transitionIndex: 3,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .childUp {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.pass)],
                        transitionIndex: 4,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .timeout {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failInvokeNotStarted)],
                        transitionIndex: 5,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

    /// Runs one transition's executable content (W3C SCXML 3.13), between the
    /// microstep's exits and its entries.
    public func executeTransitionContent(source: InvokeParamErrorStartsTheChildState, transitionIndex: Int, engine: Engine<InvokeParamErrorStartsTheChildPolicy>) {
        switch source {
        case .paramPhase:
            switch transitionIndex {
            case 0:
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                sceBlock: do {

                // W3C SCXML 5.4: <assign location="sawParamError">
                if !assignData("sawParamError", "1") {
                    raiseExecutionError("<assign> to 'sawParamError' failed", engine: engine)
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }

                }
            default:
                break
            }
        default:
            break
        }
    }}
